package ru.kryuch.krtg.searcher.service;import jakarta.transaction.Transactional;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.util.CollectionUtils;import ru.kryuch.krtg.searcher.entity.ResumeEntity;import ru.kryuch.krtg.searcher.repository.ResumeRepository;import ru.kryuch.krtg.searcher.util.UserUtil;import java.util.List;@Service@RequiredArgsConstructorpublic class ResumeService {	private final ResumeRepository resumeRepository;	public String getResume() {		Integer userId = UserUtil.getCurrentUser().getId();		List<ResumeEntity> resumeEntityList = resumeRepository.findAllByUserId(userId);		if (CollectionUtils.isEmpty(resumeEntityList)) {			return "";		}		else {			return resumeEntityList.get(0).getValue();		}	}	@Transactional	public void setResume(String value) {		Integer userId = UserUtil.getCurrentUser().getId();		List<ResumeEntity> resumeEntityList = resumeRepository.findAllByUserId(userId);		if (CollectionUtils.isEmpty(resumeEntityList)) {			ResumeEntity resumeEntity = new ResumeEntity();			resumeEntity.setUserId(userId);			resumeEntity.setValue(value);			resumeRepository.save(resumeEntity);		}		else {			resumeEntityList.get(0).setValue(value);		}	}}